insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('c1d74095-8b96-4cf7-a780-083f1defc11e', 3, 'Por transitividad, k, l y m son paralelas. Una recta perpendicular a k también lo es a m; por eso j y m son perpendiculares. j y n son paralelas.');

