insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('e8d1778d-8567-4ff7-a2fb-6bac3aedf4e7', 3, 'El pago fijo diario se recibe una sola vez. La ecuación correcta es y = 2.500x + 25.000. La propuesta multiplica indebidamente el pago fijo por el número de productos.');

