insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('8af477af-4a51-4957-9d18-7782d82ad66f', 1, 'Además de 2x − 5 = −3 hay que considerar 2x − 5 = 3. Las soluciones son x = 1 y x = 4. El caso negativo no es inválido: se refiere a la expresión dentro del valor absoluto.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
